import type { Post } from './model'

function domainError(code: string, message: string): Error & { code: string } {
  return Object.assign(new Error(message), { code })
}

/** Returned when a post does not exist. */
export const errNotFound = domainError('errNotFound', 'post not found')

/**
 * Port for post persistence.
 *
 * `create` persists the post and returns the stored entity: the ID is
 * generated by the model constructor, and createdAt/updatedAt come from the
 * database.
 */
export interface PostRepository {
  create(post: Post): Promise<Post>
  get(id: string): Promise<Post>
  list(): Promise<Post[]>
  update(post: Post): Promise<Post>
  delete(id: string): Promise<void>
}
